136		if ops == nil {
137			return nil // it's possible no ops are configured; fix #6893
138		}
139		for fieldName, replacements := range ops.Replace {
140			for i, r := range replacements {
141				if r.SearchRegexp == "" {
142					continue
143				}
144	
145				// Check if it contains placeholders
146				if containsPlaceholders(r.SearchRegexp) {
147					// Contains placeholders, skips precompilation, and recompiles at runtime
148					continue
149				}
150	
151				// Does not contain placeholders, safe to precompile
152				re, err := regexp.Compile(r.SearchRegexp)
153				if err != nil {
154					return fmt.Errorf("replacement %d for header field '%s': %v", i, fieldName, err)
155				}
