162	// containsPlaceholders checks if the string contains Caddy placeholder syntax {key}
163	func containsPlaceholders(s string) bool {
164		_, after, ok := strings.Cut(s, "{")
165		if !ok {
166			return false
167		}
168		closeIdx := strings.Index(after, "}")
169		if closeIdx == -1 {
170			return false
171		}
172		// Make sure there is content between the brackets
173		return closeIdx > 0
174	}
