// WriteHeader replaces the status code when a replace_status
// handler matched; the match decision itself is made lazily in the
// recorder's shouldBuffer callback, which also covers handlers
// that write a body without calling WriteHeader explicitly.
//
// EXPERIMENTAL: Subject to change or removal.
func (iw *interceptedWriter) WriteHeader(statusCode int) {
